UPDATE user_memory_settings SET enabled=#{settings.enabled},version=#{settings.version},
    updated_at=#{settings.updatedAt}
WHERE id=#{settings.id} AND user_id=#{settings.userId} AND version=#{expectedVersion}

mapper.select:
SELECT id FROM user_memory
WHERE status='PROPOSED' AND created_at<=#{expiredBeforeOrAt}
ORDER BY created_at,id LIMIT #{limit} FOR UPDATE SKIP LOCKED

SELECT  FROM user_memory WHERE user_id=#{userId}
AND status=#{status}
ORDER BY updated_at DESC,id DESC LIMIT #{limit} OFFSET #{offset}

