UPDATE user_memory SET content=#{memory.content},content_hash=#{memory.contentHash},
    status=#{memory.status},pinned=#{memory.pinned},expires_at=#{memory.expiresAt},
    version=#{memory.version},confirmed_by=#{memory.confirmedBy},
    confirmed_at=#{memory.confirmedAt},updated_by=#{memory.updatedBy},
    updated_at=#{memory.updatedAt},revoked_by=#{memory.revokedBy},revoked_at=#{memory.revokedAt}
